sp_widget.client_script:
api.controller = function($scope, $location) {

    /* widget controller */

    var c = this;

    // Navigate to another Service Portal page
    c.goToPage = function(pageId) {

        if (!pageId) {
            return;
        }

        $location.search({
            id: pageId
        });

    };

};

sp_widget.css:
/* =====================================================
   INSURANCE CLAIM HUB
   PROFESSIONAL HOME PAGE
   ===================================================== */

.claim-hub-home {
  font-family: "Segoe UI", Arial, sans-serif;
  background: #f5f8fc;
  color: #172033;
  margin: 0;
  padding: 0;
}


/* =====================================================
   HERO
   ===================================================== */

.claim-hub-home .hero {
  background:
    linear-gradient(
      135deg,
      #0757b8 0%,
      #0b6fd3 55%,
      #124c9b 100%
    );

  color: #ffffff;
  padding: 70px 25px;
  text-align: center;
}

.claim-hub-home .hero-content {
  max-width: 850px;
  margin: auto;
}

.claim-hub-home .hero-logo {
  width: 68px;
  height: 68px;

  margin: 0 auto 18px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: rgba(255,255,255,0.15);

  border: 1px solid rgba(255,255,255,0.35);

  border-radius: 18px;

  font-size: 36px;
}

.claim-hub-home .hero-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;

  margin-bottom: 12px;

  opacity: 0.9;
}

.claim-hub-home .hero h1 {
  font-size: 44px;
  font-weight: 700;

  margin: 0 0 10px;
}

.claim-hub-home .hero h2 {
  font-size: 22px;
  font-weight: 500;

  margin: 0 0 18px;
}

.claim-hub-home .hero p {
  max-width: 680px;
  margin: 0 auto 28px;

  font-size: 16px;
  line-height: 1.7;

  opacity: 0.94;
}


/* =====================================================
   HERO BUTTONS
   ===================================================== */

.claim-hub-home .hero-actions {
  display: flex;
  justify-content: center;

  gap: 14px;

  flex-wrap: wrap;
}

.claim-hub-home .btn-primary,
.claim-hub-home .btn-outline {
  min-width: 180px;

  padding: 13px 25px;

  border-radius: 7px;

  font-size: 14px;
  font-weight: 600;

  cursor: pointer;

  transition: all 0.2s ease;
}

.claim-hub-home .btn-primary {
  background: #ffffff;
  color: #0757b8;
  border: 2px solid #ffffff;
}

.claim-hub-home .btn-outline {
  background: transparent;
  color: #ffffff;
  border: 2px solid rgba(255,255,255,0.85);
}

.claim-hub-home .btn-primary:hover,
.claim-hub-home .btn-outline:hover {
  transform: translateY(-2px);
}


/* =====================================================
   SECTION HEADING
   ===================================================== */

.claim-hub-home .section-heading {
  max-width: 800px;

  margin: auto;

  text-align: center;
}

.claim-hub-home .small-title {
  color: #0b63ce;

  font-size: 11px;
  font-weight: 700;

  letter-spacing: 2px;
}

.claim-hub-home .section-heading h2 {
  color: #173b6c;

  font-size: 29px;

  margin: 8px 0 12px;
}

.claim-hub-home .section-heading p {
  color: #687386;

  line-height: 1.7;
}


/* =====================================================
   WELCOME
   ===================================================== */

.claim-hub-home .welcome {
  padding: 48px 25px 25px;

  background: #ffffff;
}


/* =====================================================
   QUICK ACTIONS
   ===================================================== */

.claim-hub-home .quick-actions {
  max-width: 1200px;

  margin: 0 auto;

  padding: 30px 25px 55px;

  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 18px;
}

.claim-hub-home .action-card {
  background: #ffffff;

  border-radius: 12px;

  padding: 25px;

  min-height: 190px;

  cursor: pointer;

  border: 1px solid #e5eaf1;

  box-shadow:
    0 4px 15px rgba(20,40,70,0.07);

  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.claim-hub-home .action-card:hover {
  transform: translateY(-5px);

  box-shadow:
    0 10px 28px rgba(20,40,70,0.13);
}

.claim-hub-home .action-icon {
  width: 48px;
  height: 48px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 11px;

  font-size: 25px;

  margin-bottom: 17px;
}

.claim-hub-home .action-content h3 {
  font-size: 18px;

  margin: 0 0 9px;

  color: #1c3154;
}

.claim-hub-home .action-content p {
  color: #687386;

  font-size: 13px;

  line-height: 1.6;

  min-height: 55px;
}

.claim-hub-home .action-content span {
  font-size: 13px;

  font-weight: 700;
}


/* CARD COLORS */

.claim-hub-home .action-blue {
  border-top: 4px solid #2684ff;
}

.claim-hub-home .action-blue .action-icon {
  background: #eaf3ff;
}

.claim-hub-home .action-blue span {
  color: #2684ff;
}


.claim-hub-home .action-green {
  border-top: 4px solid #27a56a;
}

.claim-hub-home .action-green .action-icon {
  background: #e9f8f0;
}

.claim-hub-home .action-green span {
  color: #218653;
}


.claim-hub-home .action-purple {
  border-top: 4px solid #7657d9;
}

.claim-hub-home .action-purple .action-icon {
  background: #f0ecff;
}

.claim-hub-home .action-purple span {
  color: #7657d9;
}


.claim-hub-home .action-orange {
  border-top: 4px solid #e99420;
}

.claim-hub-home .action-orange .action-icon {
  background: #fff3df;
}

.claim-hub-home .action-orange span {
  color: #d67c0b;
}


/* =====================================================
   FEATURES
   ===================================================== */

.claim-hub-home .features {
  background: #f5f8fc;

  padding: 55px 25px;
}

.claim-hub-home .feature-grid {
  max-width: 1100px;

  margin: 35px auto 0;

  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 20px;
}

.claim-hub-home .feature {
  background: #ffffff;

  text-align: center;

  padding: 30px 20px;

  border-radius: 11px;

  border: 1px solid #e6ebf2;
}

.claim-hub-home .feature-icon {
  font-size: 32px;

  margin-bottom: 12px;
}

.claim-hub-home .feature h3 {
  color: #203a62;

  font-size: 18px;
}

.claim-hub-home .feature p {
  color: #687386;

  font-size: 13px;

  line-height: 1.6;
}


/* =====================================================
   PROCESS
   ===================================================== */

.claim-hub-home .process {
  background: #ffffff;

  padding: 60px 25px;
}

.claim-hub-home .process-grid {
  max-width: 1100px;

  margin: 35px auto 0;

  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 18px;
}

.claim-hub-home .process-item {
  display: flex;

  gap: 15px;

  padding: 22px;

  border-radius: 10px;

  background: #f7f9fc;

  border: 1px solid #e5eaf0;
}

.claim-hub-home .process-number {
  flex-shrink: 0;

  width: 42px;
  height: 42px;

  border-radius: 50%;

  display: flex;

  align-items: center;
  justify-content: center;

  background: #0b63ce;

  color: #ffffff;

  font-size: 12px;

  font-weight: 700;
}

.claim-hub-home .process-item h3 {
  margin: 2px 0 7px;

  font-size: 16px;

  color: #1d3558;
}

.claim-hub-home .process-item p {
  margin: 0;

  font-size: 12px;

  color: #687386;

  line-height: 1.6;
}


/* =====================================================
   HELP
   ===================================================== */

.claim-hub-home .help-section {
  max-width: 1100px;

  margin: 50px auto;

  padding: 35px;

  border-radius: 14px;

  background:
    linear-gradient(
      135deg,
      #eaf4ff,
      #f4f8ff
    );

  border: 1px solid #d9e7f8;
}

.claim-hub-home .help-content {
  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 25px;
}

.claim-hub-home .help-content h2 {
  margin: 7px 0;

  color: #173b6c;
}

.claim-hub-home .help-content p {
  color: #687386;
}

.claim-hub-home .help-actions {
  display: flex;

  gap: 10px;

  flex-wrap: wrap;
}

.claim-hub-home .help-btn {
  padding: 11px 18px;

  border-radius: 7px;

  border: 0;

  background: #0b63ce;

  color: #ffffff;

  font-weight: 600;

  cursor: pointer;
}

.claim-hub-home .help-btn.secondary {
  background: #ffffff;

  color: #0b63ce;

  border: 1px solid #0b63ce;
}


/* =====================================================
   FOOTER
   ===================================================== */

.claim-hub-home .hub-footer {
  background: #10243f;

  color: #ffffff;

  padding: 25px 35px;

  display: flex;

  justify-content: space-between;

  align-items: center;

  gap: 20px;
}

.claim-hub-home .footer-brand {
  display: flex;

  align-items: center;

  gap: 12px;
}

.claim-hub-home .footer-shield {
  font-size: 28px;
}

.claim-hub-home .footer-brand strong {
  display: block;

  font-size: 15px;
}

.claim-hub-home .footer-brand small {
  display: block;

  margin-top: 3px;

  color: #b9c7d9;
}

.claim-hub-home .footer-text {
  color: #b9c7d9;

  font-size: 12px;
}


/* =====================================================
   RESPONSIVE
   ===================================================== */

@media (max-width: 1000px) {

  .claim-hub-home .quick-actions,
  .claim-hub-home .feature-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .claim-hub-home .process-grid {
    grid-template-columns: repeat(2, 1fr);
  }

}


@media (max-width: 650px) {

  .claim-hub-home .hero h1 {
    font-size: 32px;
  }

  .claim-hub-home .hero h2 {
    font-size: 18px;
  }

  .claim-hub-home .quick-actions,
  .claim-hub-home .feature-grid,
  .claim-hub-home .process-grid {
    grid-template-columns: 1fr;
  }

  .claim-hub-home .help-content {
    flex-direction: column;

    align-items: flex-start;
  }

  .claim-hub-home .hub-footer {
    flex-direction: column;

    align-items: flex-start;
  }

}

sp_widget.script:
(function() {
    data.portal_name = "Insurance Claim Hub";
    data.tagline = "Secure Claims. Smarter Tomorrow.";
})();
